var rm=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var fill=root.querySelector('.t214-var-gauge-fill');
var dot=root.querySelector('.t214-var-gauge-dot');
var val=root.querySelector('.t214-var-gauge-val');
var pct=root.querySelector('.t214-var-gauge-pct');
var band=root.querySelector('.t214-var-gauge-band');
var btn=root.querySelector('.t214-var-gauge-recalc');
var LEN=Math.PI*48,LIMIT=6.8,raf=0;
fill.style.strokeDasharray=LEN.toFixed(2);
fill.style.strokeDashoffset=LEN.toFixed(2);
function hue(p){return p<0.5?'#34D399':(p<0.8?'#FBBF24':'#F87171');}
function paint(p){
  var c=hue(p),a=p*Math.PI;
  fill.style.strokeDashoffset=(LEN*(1-p)).toFixed(2);
  fill.style.stroke=c;dot.style.stroke=c;band.style.color=c;
  dot.setAttribute('cx',(60-48*Math.cos(a)).toFixed(2));
  dot.setAttribute('cy',(60-48*Math.sin(a)).toFixed(2));
  val.textContent=(LIMIT*p).toFixed(2);
  pct.textContent=Math.round(p*100);
}
function run(to){
  if(raf){cancelAnimationFrame(raf);raf=0;}
  if(rm){paint(to);return;}
  var t0=0,dur=1150;
  paint(0);
  raf=requestAnimationFrame(function step(ts){
    if(!t0)t0=ts;
    var k=Math.min(1,(ts-t0)/dur),e=1-Math.pow(1-k,3);
    paint(to*e);
    if(k<1){raf=requestAnimationFrame(step);}else{raf=0;}
  });
}
var levels=[0.62,0.48,0.83,0.55,0.71],i=0;
btn.addEventListener('click',function(){
  i=(i+1)%levels.length;
  btn.classList.remove('t214-var-gauge-spin');
  void btn.offsetWidth;
  btn.classList.add('t214-var-gauge-spin');
  run(levels[i]);
});
run(levels[0]);

