var rm=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var cells=root.querySelectorAll('.t214-exposure-heat-cell');
var det=root.querySelector('.t214-exposure-heat-dv');
var DEF='book net +52.3% · gross 118.6%';
var MAX=18.4;
function show(c){
  det.textContent=c.getAttribute('data-r')+' · '+c.getAttribute('data-c')+'  net '+c.textContent+'%  gross '+c.getAttribute('data-g')+'%';
}
Array.prototype.forEach.call(cells,function(c,i){
  var v=parseFloat(c.getAttribute('data-v')),m=Math.min(1,Math.abs(v)/MAX);
  var a=(0.12+0.62*m).toFixed(3);
  c.style.background=(v>=0?'rgba(52,211,153,':'rgba(248,113,113,')+a+')';
  c.style.color=m>0.55?'#0A0C12':(v>=0?'#BBF7D9':'#FECACA');
  c.setAttribute('aria-label',c.getAttribute('data-r')+' '+c.getAttribute('data-c')+' net '+c.textContent+' percent of NAV');
  if(rm){c.classList.add('t214-exposure-heat-in');}
  else{c.style.transitionDelay=(i*20)+'ms';}
  c.addEventListener('mouseenter',function(){show(c);});
  c.addEventListener('focus',function(){show(c);});
  c.addEventListener('mouseleave',function(){det.textContent=DEF;});
  c.addEventListener('blur',function(){det.textContent=DEF;});
});
det.textContent=DEF;
if(!rm){
  setTimeout(function(){
    Array.prototype.forEach.call(cells,function(c){c.classList.add('t214-exposure-heat-in');});
    setTimeout(function(){Array.prototype.forEach.call(cells,function(c){c.style.transitionDelay='0ms';});},900);
  },30);
}

