js:
var rm=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var grid=root.querySelector('.t214-corr-matrix-grid');
var cells=root.querySelectorAll('.t214-corr-matrix-cell');
var cols=root.querySelectorAll('.t214-corr-matrix-col');
var rows=root.querySelectorAll('.t214-corr-matrix-row');
var cap=root.querySelector('.t214-corr-matrix-cv');
var NAM=['SPX','NDX','TLT','GLD','DXY'];
var DEF='GLD ↔ DXY strongest inverse pair  ρ −0.63';
Array.prototype.forEach.call(cells,function(c){
  var v=parseFloat(c.getAttribute('data-v')),r=+c.getAttribute('data-r'),k=+c.getAttribute('data-c');
  if(Math.abs(v)!==1){
    var a=(0.10+0.68*Math.abs(v)).toFixed(3);
    c.style.background=(v>=0?'rgba(96,165,250,':'rgba(251,146,60,')+a+')';
    c.style.color=Math.abs(v)>0.55?'#0A0C12':'#E9EDF6';
    c.setAttribute('aria-label',NAM[r]+' versus '+NAM[k]+', correlation '+v.toFixed(2));
  }
  if(rm){c.classList.add('t214-corr-matrix-in');}
  else{c.style.transitionDelay=((r+k)*45)+'ms';}
  function lit(){
    grid.classList.add('t214-corr-matrix-lit');
    Array.prototype.forEach.call(cells,function(o){
      var hot=(+o.getAttribute('data-r')===r)||(+o.getAttribute('data-c')===k);
      o.classList.toggle('t214-corr-matrix-hot',hot);
    });
    Array.prototype.forEach.call(cols,function(o){o.classList.toggle('t214-corr-matrix-axis',+o.getAttribute('data-c')===k);});
    Array.prototype.forEach.call(rows,function(o){o.classList.toggle('t214-corr-matrix-axis',+o.getAttribute('data-r')===r);});
    cap.textContent=NAM[r]+' ↔ '+NAM[k]+'  ρ '+(r===k?'1.00':c.textContent)+'  · 90d';
  }
  c.addEventListener('mouseenter',lit);
  c.addEventListener('focus',lit);
});
function clear(){
  grid.classList.remove('t214-corr-matrix-lit');
  Array.prototype.forEach.call(cells,function(o){o.classList.remove('t214-corr-matrix-hot');});
  Array.prototype.forEach.call(cols,function(o){o.classList.remove('t214-corr-matrix-axis');});
  Array.prototype.forEach.call(rows,function(o){o.classList.remove('t214-corr-matrix-axis');});
  cap.textContent=DEF;
}
grid.addEventListener('mouseleave',clear);
grid.addEventListener('focusout',function(e){if(!grid.contains(e.relatedTarget)){clear();}});
cap.textContent=DEF;
if(!rm){
  setTimeout(function(){
    Array.prototype.forEach.call(cells,function(c){c.classList.add('t214-corr-matrix-in');});
    setTimeout(function(){Array.prototype.forEach.call(cells,function(c){c.style.transitionDelay='0ms';});},900);
  },30);
}

