js:
var rm=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var NS='http://www.w3.org/2000/svg';
var DD=[0,0,-1.2,-0.4,0,0,-2.1,-3.6,-2.2,-0.8,0,-1.5,-4.2,-7.8,-11.3,-14.6,-16.9,-18.4,-17.2,-15.1,-12.4,-13.8,-11,-8.6,-6.2,-4.4,-2.9,-1.1,0,-0.6,-2.4,-1.7,-0.5,0,0,-1.9,-3.3,-2.6,-1.4,-0.7,-2];
var n=DD.length,L=6,R=274,T=8,B=74,SC=20,PK=10,TR=17,RC=28;
function X(i){return L+i*(R-L)/(n-1);}
function Y(v){return T+(Math.abs(v)/SC)*(B-T);}
var MN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var ML=[31,28,31,30,31,30,31,31,30,31,30,31];
var dm=0,dv=10,dates=[];
for(var i=0;i<n;i++){dates.push((dv<10?'0':'')+dv+' '+MN[dm]);dv+=7;while(dv>ML[dm]){dv-=ML[dm];dm=(dm+1)%12;}}
var g=root.querySelector('.t214-dd-curve-grid');
[-5,-10,-15].forEach(function(v){
  var ln=document.createElementNS(NS,'line');
  ln.setAttribute('class','t214-dd-curve-gl');
  ln.setAttribute('x1',L);ln.setAttribute('x2',R);ln.setAttribute('y1',Y(v));ln.setAttribute('y2',Y(v));
  g.appendChild(ln);
  var tx=document.createElementNS(NS,'text');
  tx.setAttribute('class','t214-dd-curve-gt');
  tx.setAttribute('x',R);tx.setAttribute('y',Y(v)-2);tx.setAttribute('text-anchor','end');
  tx.textContent='−'+Math.abs(v);
  g.appendChild(tx);
});
var pts=[];
for(var j=0;j<n;j++){pts.push(X(j).toFixed(1)+','+Y(DD[j]).toFixed(1));}
var line=root.querySelector('.t214-dd-curve-line');
var area=root.querySelector('.t214-dd-curve-area');
line.setAttribute('d','M'+pts.join(' L'));
area.setAttribute('d','M'+X(0).toFixed(1)+','+T+' L'+pts.join(' L')+' L'+X(n-1).toFixed(1)+','+T+' Z');
var peak=root.querySelector('.t214-dd-curve-peak');
var trough=root.querySelector('.t214-dd-curve-trough');
peak.setAttribute('cx',X(PK).toFixed(1));peak.setAttribute('cy',Y(DD[PK]).toFixed(1));
trough.setAttribute('cx',X(TR).toFixed(1));trough.setAttribute('cy',Y(DD[TR]).toFixed(1));
var cross=root.querySelector('.t214-dd-curve-cross');
var cur=root.querySelector('.t214-dd-curve-cursor');
var val=root.querySelector('.t214-dd-curve-val');
var day=root.querySelector('.t214-dd-curve-day');
function show(i){
  i=Math.max(0,Math.min(n-1,i));
  var x=X(i),y=Y(DD[i]);
  cross.setAttribute('x1',x.toFixed(1));cross.setAttribute('x2',x.toFixed(1));cross.setAttribute('y2',y.toFixed(1));
  cur.setAttribute('cx',x.toFixed(1));cur.setAttribute('cy',y.toFixed(1));
  val.textContent=(DD[i]<0?'−':'')+Math.abs(DD[i]).toFixed(1)+'%';
  val.style.color=DD[i]<0?'#F87171':'#8B94A9';
  day.textContent=dates[i];
  cursorIdx=i;
}
var cursorIdx=TR;
root.querySelector('.t214-dd-curve-pd').textContent=dates[PK];
root.querySelector('.t214-dd-curve-td').textContent=dates[TR];
root.querySelector('.t214-dd-curve-dur').textContent=(TR-PK)*7+'d down · '+(RC-TR)*7+'d back';
var plot=root.querySelector('.t214-dd-curve-plot');
plot.addEventListener('mousemove',function(e){
  var r=plot.getBoundingClientRect();
  show(Math.round(((e.clientX-r.left)/r.width)*(n-1)));
