  if(rm){bar.style.width=w;pct.textContent=(u>100?'▲ ':'')+u.toFixed(1)+'%';return;}
  setTimeout(function(){bar.style.width=w;},90+i*120);
  var t0=0,dur=800;
  setTimeout(function(){
    requestAnimationFrame(function step(ts){
      if(!t0)t0=ts;
