.rsk6-kyc-stepper__top{display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:10px}
.rsk6-kyc-stepper__ttl{font-size:9.5px;letter-spacing:.04em;color:#B9C4D6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rsk6-kyc-stepper__chip{flex:none;font:700 8px/1 var(--rsk6-mono);letter-spacing:.07em;color:var(--rsk6-wr);background:rgba(240,180,41,.12);border:1px solid rgba(240,180,41,.34);border-radius:4px;padding:3px 5px}
.rsk6-kyc-stepper__rail{position:relative;display:grid;grid-template-columns:repeat(4,1fr);align-items:start}
.rsk6-kyc-stepper__line{position:absolute;left:12.5%;right:12.5%;top:8px;height:2px;background:#212A3A;border-radius:2px}
.rsk6-kyc-stepper__prog{position:absolute;left:12.5%;top:8px;height:2px;width:0;background:linear-gradient(90deg,var(--rsk6-ok),var(--rsk6-wr));border-radius:2px;transition:width .8s cubic-bezier(.3,.9,.3,1)}
.rsk6-kyc-stepper__step{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:4px;border:0;background:none;padding:0;cursor:pointer;font:inherit}
.rsk6-kyc-stepper__step:focus-visible{outline:2px solid #6FA8FF;outline-offset:3px;border-radius:6px}
.rsk6-kyc-stepper__dot{display:flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:50%;box-sizing:border-box;border:2px solid #2A3546;background:#111826;color:#6B7891;font:700 9px/1 var(--rsk6-mono);transition:transform .16s ease,border-color .2s ease,color .2s ease,background .2s ease}
.rsk6-kyc-stepper__step[data-st="done"] .rsk6-kyc-stepper__dot{border-color:var(--rsk6-ok);color:#08221B;background:var(--rsk6-ok)}
.rsk6-kyc-stepper__step[data-st="live"] .rsk6-kyc-stepper__dot{border-color:var(--rsk6-wr);color:var(--rsk6-wr);background:#1B1A12;animation:rsk6-kyc-stepper-ring 2s ease-out infinite}
.rsk6-kyc-stepper__step:hover .rsk6-kyc-stepper__dot{transform:scale(1.12)}
.rsk6-kyc-stepper__cap{font-size:8px;letter-spacing:.02em;color:#66738A;text-align:center;line-height:1.15;max-width:66px}
.rsk6-kyc-stepper__step[data-st="done"] .rsk6-kyc-stepper__cap{color:#8FA0B8}
.rsk6-kyc-stepper__step[data-st="live"] .rsk6-kyc-stepper__cap{color:#E8EDF7}
.rsk6-kyc-stepper__step[aria-pressed="true"] .rsk6-kyc-stepper__cap{color:#fff;text-decoration:underline;text-underline-offset:2px}
@keyframes rsk6-kyc-stepper-ring{0%{box-shadow:0 0 0 0 rgba(240,180,41,.45)}70%{box-shadow:0 0 0 7px rgba(240,180,41,0)}100%{box-shadow:0 0 0 0 rgba(240,180,41,0)}}
.rsk6-kyc-stepper__det{margin-top:9px;font:500 9.5px/1.25 var(--rsk6-mono);color:#C3CDDF;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rsk6-kyc-stepper__foot{display:flex;justify-content:space-between;gap:8px;margin-top:6px;padding-top:6px;border-top:1px solid var(--rsk6-ln);font-size:9px;color:var(--rsk6-dm)}
.rsk6-kyc-stepper__risk{color:var(--rsk6-wr);font-family:var(--rsk6-mono)}
@media (prefers-reduced-motion:reduce){.rsk6-kyc-stepper__prog,.rsk6-kyc-stepper__dot{transition:none}.rsk6-kyc-stepper__step[data-st="live"] .rsk6-kyc-stepper__dot{animation:none}}

