var TXT=['Identity & verification — cleared 18 Aug · 4 UBOs matched','Sanctions / PEP — 0 hits · OFAC+EU refreshed 20 Aug','Source of Funds — docs requested 22 Aug · SLA 3d left','Approval — pending MLRO sign-off · queued'];
var steps=Array.prototype.slice.call(root.querySelectorAll('.rsk6-kyc-stepper__step'));
var det=root.querySelector('.rsk6-kyc-stepper__det'),prog=root.querySelector('.rsk6-kyc-stepper__prog');
var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var live=2,cur=live;
function sel(i,focus){cur=i;steps.forEach(function(s,j){s.setAttribute('aria-pressed',j===i?'true':'false');s.tabIndex=j===i?0:-1;});det.textContent=TXT[i];if(focus)steps[i].focus();}
steps.forEach(function(s,i){s.setAttribute('aria-current',s.getAttribute('data-st')==='live'?'step':'false');s.addEventListener('click',function(){sel(i,false);});
 s.addEventListener('keydown',function(e){if(e.key==='ArrowRight'||e.key==='ArrowDown'){sel(Math.min(steps.length-1,cur+1),true);e.preventDefault();}else if(e.key==='ArrowLeft'||e.key==='ArrowUp'){sel(Math.max(0,cur-1),true);e.preventDefault();}});});
sel(live,false);
var w=(live/(steps.length-1))*75;
if(rm)prog.style.width=w+'%';else requestAnimationFrame(function(){prog.style.width=w+'%';});
